// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        bool success;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            success = true;
            assertTrue(ret == true);
        } catch {
            success = false;
        }
    }
}
// No adversarial helper is needed because low-level calls to EOAs (fuzzed addresses) always succeed, and the difference is in the return value, not in call failure.
